import{_ as e,c as n,o as r,ag as o}from"./chunks/framework.Ci10AEOF.js";const s="/docs-website/assets/destination_channel_writer.CWmnQUtE.png",d="/docs-website/assets/destination_database_writer.CJ5TQGiB.png",a="/docs-website/assets/destination_dicom_sender.DPEyegUF.png",i="/docs-website/assets/destination_document_writer.CvP68VL_.png",h="/docs-website/assets/destination_file_writer.BAQS9S9r.png",g="/docs-website/assets/destination_http_sender.CSq7eGpz.png",c="/docs-website/assets/destination_javascript_writer.FauEa4ZO.png",l="/docs-website/assets/destination_jms_sender.91zsElMU.png",p="/docs-website/assets/destination_smtp_sender.Cy0XEMYN.png",u="/docs-website/assets/destination_tcp_sender.D9qYjfY6.png",m="/docs-website/assets/destination_web_service_sender.DRX6oPMI.png",P=JSON.parse('{"title":"Destination Connectors","description":"Every destination connector and the settings it exposes","frontmatter":{"title":"Destination Connectors","description":"Every destination connector and the settings it exposes"},"headers":[],"relativePath":"engine/connector_reference_destinations.md","filePath":"engine/connector_reference_destinations.md","lastUpdated":1793057853000}'),b={name:"engine/connector_reference_destinations.md"};function f(y,t,S,w,T,v){return r(),n("div",null,t[0]||(t[0]=[o('<h1 id="destination-connectors" tabindex="-1">Destination connectors <a class="header-anchor" href="#destination-connectors" aria-label="Permalink to &quot;Destination connectors&quot;">​</a></h1><p>A channel has at least one destination and may have many. Each has its own filter, transformer, and connector, and it does not have to send anything: its filter can stop the message, and a JavaScript Writer may only run a script. Eleven types ship with the engine.</p><table tabindex="0"><thead><tr><th>Connector</th><th>Sends data by</th></tr></thead><tbody><tr><td><a href="#channel-writer">Channel Writer</a></td><td>Handing the message to another channel on the same engine</td></tr><tr><td><a href="#database-writer">Database Writer</a></td><td>Running a statement against a JDBC database</td></tr><tr><td><a href="#dicom-sender">DICOM Sender</a></td><td>Opening a DICOM association to a remote AE</td></tr><tr><td><a href="#document-writer">Document Writer</a></td><td>Rendering a PDF or RTF</td></tr><tr><td><a href="#file-writer">File Writer</a></td><td>Writing to a local directory, FTP, SFTP, S3, SMB, or WebDAV</td></tr><tr><td><a href="#http-sender">HTTP Sender</a></td><td>Making an HTTP request</td></tr><tr><td><a href="#javascript-writer">JavaScript Writer</a></td><td>Running a script</td></tr><tr><td><a href="#jms-sender">JMS Sender</a></td><td>Publishing to a JMS queue or topic</td></tr><tr><td><a href="#smtp-sender">SMTP Sender</a></td><td>Sending email</td></tr><tr><td><a href="#tcp-sender">TCP Sender</a></td><td>Opening a TCP connection, MLLP included</td></tr><tr><td><a href="#web-service-sender">Web Service Sender</a></td><td>Calling a SOAP operation</td></tr></tbody></table><h2 id="settings-outside-the-connector-s-own-fields" tabindex="-1">Settings outside the connector&#39;s own fields <a class="header-anchor" href="#settings-outside-the-connector-s-own-fields" aria-label="Permalink to &quot;Settings outside the connector&#39;s own fields&quot;">​</a></h2><p>One block sits above the connector&#39;s own configuration, and every destination type has it. It controls the queue and what happens when a send fails. <strong>Queue Messages</strong>, <strong>Validate Response</strong> and <strong>Reattach Attachments</strong> are on the panel itself; the rest open from the wrench button beside <strong>Advanced Queue Settings</strong>. The queue-only settings are greyed out while <strong>Queue Messages</strong> is Never, and the retry settings stay available for Never and On Failure.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Queue Messages</strong></td><td>Never</td><td>Never, On Failure, or Always. Decides whether a failed send, or every send, goes to this destination&#39;s queue. Not every failure queues: a refused connection does, but a JavaScript Writer script that throws gives ERROR and is not queued; return <code>QUEUED</code> from the script to queue the message. On Failure sends directly only while the queue is empty; otherwise a new message joins the queue. See <a href="./queueing.html">Queueing</a></td></tr><tr><td><strong>Retry Count Before Queue/Error</strong></td><td>0</td><td>Retries after the first failed attempt before the message queues or errors, so 0 means one attempt. Enabled only when <strong>Queue Messages</strong> is Never or On Failure</td></tr><tr><td><strong>Retry Interval (ms)</strong></td><td>10000</td><td>Wait between those attempts. Enabled when the queue is on or <strong>Retry Count Before Queue/Error</strong> is above 0</td></tr><tr><td><strong>Rotate Queue</strong></td><td>No</td><td>Move a failing message to the back of the queue instead of blocking behind it. Queue on only</td></tr><tr><td><strong>Queue Threads</strong></td><td>1</td><td>Threads draining the queue. More than one drains it in parallel, so order is no longer guaranteed except within a <strong>Thread Assignment Variable</strong> group. Queue on only</td></tr><tr><td><strong>Thread Assignment Variable</strong></td><td></td><td>Groups messages onto the same queue thread, so ordering is kept within a group when <strong>Rotate Queue</strong> is No. Enabled only when <strong>Queue Threads</strong> is above 1</td></tr><tr><td><strong>Queue Buffer Size</strong></td><td>Default Queue Buffer Size from Settings</td><td>Messages held in memory before falling back to the database. The Administrator fills in the Settings value for a new destination and refuses to save a value of 0 or less. Queue on only</td></tr><tr><td><strong>Include Filter/Transformer</strong></td><td>No</td><td>Re-run the destination&#39;s filter and transformer on each queue retry. Enabled only when the queue is on and <strong>Regenerate Template</strong> is Yes</td></tr><tr><td><strong>Regenerate Template</strong></td><td>No</td><td>Replace the variables in the template and the other connector settings again on each retry, picking up map changes. Queue on only</td></tr><tr><td><strong>Validate Response</strong></td><td>No</td><td>Run the response validator of the response transformer&#39;s inbound data type on the reply. This works only when that data type has a Response Validation section; a failed validation marks the message queued or errored. For HL7 v2, an error or rejected ACK, or a control ID that does not match, gives ERROR; a blank reply, or one that is not a valid ACK, gives QUEUED, which becomes ERROR when the queue is off. Available on the Channel Writer, Database Writer, HTTP Sender, JavaScript Writer, TCP Sender, and Web Service Sender, and greyed out on the DICOM Sender, Document Writer, File Writer, JMS Sender, and SMTP Sender. The TCP Sender is the only type that ships with this on</td></tr><tr><td><strong>Reattach Attachments</strong></td><td>Yes</td><td>Re-insert attachment content before sending. No effect on the JMS Sender or the JavaScript Writer</td></tr></tbody></table><p>The queue is <strong>off by default on every destination</strong>.</p><p>Field values are run through <a href="./velocity_variable_replacement.html">Velocity replacement</a> before the send, so a directory, a filename, a URL, a subject line, or a header can carry data from the message. The JavaScript Writer is the exception: it has no templated fields.</p><h2 id="channel-writer" tabindex="-1">Channel Writer <a class="header-anchor" href="#channel-writer" aria-label="Permalink to &quot;Channel Writer&quot;">​</a></h2><p>Hands the message to another channel on the same engine. A Channel Reader is the usual receiver, but the target channel&#39;s source does not have to be one: a channel with an HTTP Listener source receives the message and runs its destinations.</p><p><img src="'+s+'" alt="The Channel Writer settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Channel Id</strong></td><td>none</td><td>The receiving channel</td></tr><tr><td><strong>Template</strong></td><td><code>${message.encodedData}</code></td><td>What the receiving channel gets as its raw message</td></tr><tr><td><strong>Message Metadata</strong></td><td></td><td>Map variables to pass along. They arrive in the receiving channel&#39;s <strong>source map</strong>, not its channel map</td></tr></tbody></table><h2 id="database-writer" tabindex="-1">Database Writer <a class="header-anchor" href="#database-writer" aria-label="Permalink to &quot;Database Writer&quot;">​</a></h2><p>Runs an insert, update, or delete against a database. Write it in SQL or build it in JavaScript.</p><p><img src="'+d+'" alt="The Database Writer settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Driver</strong></td><td>Please Select One</td><td>JDBC driver. Required, JavaScript mode included. See <a href="./connector_reference_sources.html#jdbc-drivers-and-url-templates">drivers and URL templates</a></td></tr><tr><td><strong>URL</strong></td><td></td><td>JDBC connection URL</td></tr><tr><td><strong>Username</strong> / <strong>Password</strong></td><td></td><td>Database credentials</td></tr><tr><td><strong>Use JavaScript</strong></td><td>No</td><td>Build the statement in JavaScript instead of SQL</td></tr><tr><td><strong>SQL</strong> / <strong>JavaScript</strong></td><td></td><td>The statement. The <strong>Generate</strong> buttons above it build a starting statement, or in JavaScript mode a connection block, from the settings above. In SQL mode each <code>${}</code> is bound as a parameter rather than pasted in as text; see <a href="./velocity_variable_replacement.html#where-velocity-is-used">Where Velocity is used</a></td></tr></tbody></table><p><strong>JavaScript mode</strong></p><p>As on the <a href="./connector_reference_sources.html#database-reader">Database Reader</a>, the connector opens no database connection in this mode and the script opens its own. <strong>Driver</strong> is required either way. While it reads <em>Please Select One</em> the Administrator saves the channel disabled and shows an error dialog listing the problem. <strong>URL</strong> is validated only when Use JavaScript is No, and the credentials are never validated. <strong>Generate: Connection</strong>, enabled only in this mode, pastes all four values, the password in plain text among them, into a connection block at the top of the script, and <strong>Generate: Insert</strong> inserts a <code>dbConn.executeUpdate(...)</code> line at the caret for the table you pick. Those values are string literals in the script from then on. Editing the fields does not change them, and the connector&#39;s own copies are never read at runtime.</p><p>The generated block opens a connection and closes it in a <code>finally</code>, with nothing in between until you add the statements yourself. What the script returns decides the response: nothing at all is a SENT with <em>Database write success</em>, a <code>Response</code> is used as-is, a <code>Status</code> sets only the status, and anything else becomes the response data.</p><p>Clicking the <strong>Use JavaScript</strong> radio rewrites the script field: Yes replaces its contents with the generated block, No empties it. Reopening a saved channel does not.</p><h2 id="dicom-sender" tabindex="-1">DICOM Sender <a class="header-anchor" href="#dicom-sender" aria-label="Permalink to &quot;DICOM Sender&quot;">​</a></h2><p>Opens an association to a remote application entity and sends the message as DICOM.</p><p><img src="'+a+'" alt="The DICOM Sender settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Remote Host</strong></td><td>127.0.0.1</td><td>Destination host</td></tr><tr><td><strong>Remote Port</strong></td><td>104</td><td>Destination port</td></tr><tr><td><strong>Remote Application Entity</strong></td><td></td><td>AE title being called. Blank calls <code>DCMRCV</code></td></tr><tr><td><strong>Local Host</strong> / <strong>Local Port</strong> / <strong>Local Application Entity</strong></td><td></td><td><strong>Local Application Entity</strong> is the AE title the connector calls with. In 4.7.0 <strong>Local Host</strong> and <strong>Local Port</strong> do not change the connection&#39;s source address or port: set to 127.0.0.2 and 7795, or either one alone, the connection still comes from 127.0.0.1 on an ephemeral port</td></tr><tr><td><strong>Template</strong></td><td><code>${DICOMMESSAGE}</code></td><td>Content sent</td></tr><tr><td><strong>User Name</strong> / <strong>Pass Code</strong></td><td></td><td>Credentials for user identity negotiation. <strong>Pass Code</strong> is effective only with a <strong>User Name</strong></td></tr><tr><td><strong>Request Positive User Identity Response</strong></td><td>No</td><td>Require the remote AE to confirm the identity. Effective only with a <strong>User Name</strong></td></tr><tr><td><strong>Request Storage Commitment</strong></td><td>No</td><td>Ask for a storage commitment after the send</td></tr><tr><td><strong>Priority</strong></td><td>Medium</td><td>High, Medium, or Low. Sets the priority field of the C-STORE request. In 4.7.0 Medium sends 0, Low sends 1 and High sends 2, while the DICOM standard defines 0 as medium, 1 as high and 2 as low, so High and Low are swapped on the wire</td></tr><tr><td><strong>Max Async operations</strong></td><td>0</td><td>Maximum outstanding operations invoked asynchronously. Unlimited by default</td></tr><tr><td><strong>Pack PDV</strong></td><td>No</td><td>Pack command and data PDVs into one P-DATA-TF PDU</td></tr><tr><td><strong>Default Presentation Syntax</strong></td><td>No</td><td>Offer the default transfer syntax in its own presentation context</td></tr><tr><td><strong>TCP Delay</strong></td><td>Yes</td><td>Leave Nagle&#39;s algorithm on</td></tr></tbody></table><p><strong>Timing</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>TCP Connection Timeout (ms)</strong></td><td>0</td><td>Connect timeout. 0 waits indefinitely</td></tr><tr><td><strong>Timeout A-ASSOCIATE-AC (ms)</strong></td><td>5000</td><td>Wait for the association to be accepted</td></tr><tr><td><strong>DIMSE-RSP timeout (s)</strong></td><td>60</td><td>Wait for a DIMSE response</td></tr><tr><td><strong>DIMSE-RSP interval period (s)</strong></td><td>10</td><td>Interval for the association reaper</td></tr><tr><td><strong>A-RELEASE-RP timeout (s)</strong></td><td>5</td><td>Has no effect in 4.7.0: the value is passed to the DICOM library, which never reads it</td></tr><tr><td><strong>Socket Close Delay After A-ABORT (ms)</strong></td><td>50</td><td>Delay before closing after an abort</td></tr><tr><td><strong>Shutdown delay (ms)</strong></td><td>1000</td><td>Delay before the listening socket is closed</td></tr></tbody></table><p><strong>Buffers</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>P-DATA-TF PDUs max length sent (KB)</strong></td><td>16</td><td>Maximum PDU length sent</td></tr><tr><td><strong>P-DATA-TF PDUs max length received (KB)</strong></td><td>16</td><td>Maximum PDU length accepted</td></tr><tr><td><strong>Send Socket Buffer Size (KB)</strong></td><td>0</td><td>0 leaves the OS default</td></tr><tr><td><strong>Receive Socket Buffer Size (KB)</strong></td><td>0</td><td>0 leaves the OS default</td></tr><tr><td><strong>Transcoder Buffer Size (KB)</strong></td><td>1</td><td>Buffer used when transcoding</td></tr></tbody></table><p><strong>TLS</strong></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>TLS</strong></td><td>No TLS</td><td>No TLS, 3DES, AES, or Without. No TLS greys out every other setting in this table. With the JDK&#39;s default security settings on Java 17 and 21, 3DES, AES and Without fail; see the box under <a href="./connector_reference_sources.html#dicom-listener">DICOM Listener</a></td></tr><tr><td><strong>Client Authentication TLS</strong></td><td>Yes</td><td>Enable client authentication for TLS</td></tr><tr><td><strong>Accept ssl v2 TLS handshake</strong></td><td>Yes</td><td>Yes removes the SSLv2Hello handshake from the connector&#39;s protocols, so the label reads opposite to its effect</td></tr><tr><td><strong>Keystore</strong> / <strong>Keystore Password</strong> / <strong>Key Password</strong></td><td></td><td>Identity presented to the remote AE</td></tr><tr><td><strong>Trust Store</strong> / <strong>Trust Store Password</strong></td><td></td><td>Certificates this connector will trust</td></tr></tbody></table><p>With TLS on, fill in <strong>Keystore</strong> and <strong>Trust Store</strong>: left blank, the sender falls back to the DICOM library&#39;s sample paths, <code>resource:tls/test_sys_1.p12</code> and <code>resource:tls/mesa_certs.jks</code>, which the 4.7.0 release does not ship.</p><h2 id="document-writer" tabindex="-1">Document Writer <a class="header-anchor" href="#document-writer" aria-label="Permalink to &quot;Document Writer&quot;">​</a></h2><p>Renders the message as a document and writes it out.</p><p><img src="'+i+'" alt="The Document Writer settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Output</strong></td><td>File</td><td>File, Attachment, or Both. Attachment and Both attach the rendered document to the message, and the destination&#39;s response contains the attachment Id. Attachment greys out <strong>Directory</strong>, <strong>File Name</strong>, and <strong>Test Write</strong></td></tr><tr><td><strong>Directory</strong></td><td></td><td>Where the file goes. <strong>Test Write</strong> checks that the directory can be written</td></tr><tr><td><strong>File Name</strong></td><td></td><td>Name of the file written</td></tr><tr><td><strong>Document Type</strong></td><td>PDF</td><td>PDF or RTF</td></tr><tr><td><strong>Encrypted</strong></td><td>No</td><td>Encrypt the PDF. RTF greys this out</td></tr><tr><td><strong>Password</strong></td><td></td><td>Password on the encrypted PDF. Enabled, and required, only when <strong>Encrypted</strong> is Yes</td></tr><tr><td><strong>Page Size</strong></td><td>8.5 x 11 inches</td><td>Width, height, and unit, with a drop-down of standard page sizes beside the unit. Width and height must be above 0, and PDFs enforce a minimum of 26 mm</td></tr><tr><td><strong>HTML Template</strong></td><td></td><td>The HTML rendered into the document</td></tr></tbody></table><h2 id="file-writer" tabindex="-1">File Writer <a class="header-anchor" href="#file-writer" aria-label="Permalink to &quot;File Writer&quot;">​</a></h2><p>Writes the message to a file. <strong>Method</strong> is the first choice: it decides how the location is addressed, whether credentials apply, which connection fields are available, and which <strong>File Exists</strong> options you get.</p><p><img src="'+h+'" alt="The File Writer settings on the channel editor&#39;s Destinations tab"></p><h3 id="method" tabindex="-1">Method <a class="header-anchor" href="#method" aria-label="Permalink to &quot;Method&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Location</th><th>Credentials</th><th>Also enables</th></tr></thead><tbody><tr><td><strong>file</strong></td><td><strong>Directory</strong>, a single field</td><td>none</td><td>nothing</td></tr><tr><td><strong>ftp</strong></td><td><code>ftp://</code> host, then a path</td><td>Anonymous, or a username and password</td><td>Passive Mode, Validate Connection, Timeout, Advanced Options</td></tr><tr><td><strong>sftp</strong></td><td><code>sftp://</code> host, then a path</td><td>A username always, and a password unless the Advanced Options use a different authentication</td><td>Timeout, Advanced Options</td></tr><tr><td><strong>Amazon S3</strong></td><td><strong>S3 Bucket</strong>, then a path</td><td>Anonymous, or an AWS Access Key ID and Secret Access Key. Neither is required when the Advanced Options use the default credential provider chain</td><td>Timeout, Advanced Options</td></tr><tr><td><strong>smb</strong></td><td><code>smb://</code> host, then a path</td><td>always required</td><td>Timeout, Advanced Options</td></tr><tr><td><strong>webdav</strong></td><td><code>http://</code> or <code>https://</code> host, then a path</td><td>Anonymous, or a username and password</td><td>Secure Mode</td></tr></tbody></table><p>Two methods restrict what else you can choose. <strong>Append is not available under S3 or WebDAV</strong>, so File Exists offers only Overwrite and Error, and selecting either method switches an existing Append setting to Overwrite. S3 additionally forces <strong>Create Temp File</strong> to No. Under S3 the credential fields are relabelled <strong>AWS Access Key ID</strong> and <strong>AWS Secret Access Key</strong>.</p><div class="danger custom-block"><p class="custom-block-title">Broken in 4.7.0</p><p>A File Writer set to <strong>webdav</strong> writes nothing: the message is left at RECEIVED, and the server log shows <code>NoClassDefFoundError: org/jdom/input/DOMBuilder</code>. Fix proposed in <a href="https://github.com/OpenIntegrationEngine/engine/pull/546" target="_blank" rel="noreferrer">engine PR #546</a>, not yet in a release.</p></div><p>On Windows, <strong>Directory</strong> under <code>file</code> can be a UNC path such as <code>\\\\server\\share\\outbound</code>. The Administrator stores it with forward slashes, <code>//server/share/outbound</code>, which Windows still reads as the same share. The account the OIE service runs as needs access to the share. On Linux, mount the share, in <code>/etc/fstab</code> or with an automounter, and point the <code>file</code> method at the mount point.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Timeout (ms)</strong></td><td>10000</td><td>How long to wait when connecting</td></tr><tr><td><strong>Keep Connection Open</strong></td><td>Yes</td><td>Keep the connection open after writing</td></tr><tr><td><strong>Max Idle Time (ms)</strong></td><td>0</td><td>Idle time before a kept connection is closed. 0 is infinite. Enabled only when <strong>Keep Connection Open</strong> is Yes</td></tr><tr><td><strong>Secure Mode</strong></td><td>Yes</td><td>WebDAV over HTTPS</td></tr><tr><td><strong>Passive Mode</strong></td><td>Yes</td><td>FTP passive transfers</td></tr><tr><td><strong>Validate Connection</strong></td><td>Yes</td><td>Test the connection before writing</td></tr></tbody></table><p>Per-protocol extras sit behind <strong>Advanced Options</strong>; see <a href="./connector_reference_sources.html#file-protocol-advanced-settings">file protocol advanced settings</a>.</p><h3 id="writing-the-file" tabindex="-1">Writing the file <a class="header-anchor" href="#writing-the-file" aria-label="Permalink to &quot;Writing the file&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>File Name</strong></td><td></td><td>Name of the file written</td></tr><tr><td><strong>File Exists</strong></td><td>Append</td><td>Append, Overwrite, or Error when the file is already there. Append is unavailable under S3 and WebDAV</td></tr><tr><td><strong>Create Temp File</strong></td><td>No</td><td>Write under a temporary name and rename on completion. Not available under S3, and greyed out and set to No whenever <strong>File Exists</strong> is Append</td></tr><tr><td><strong>File Type</strong></td><td>Text</td><td>Text or Binary. Binary base64 decodes the content before writing</td></tr><tr><td><strong>Encoding</strong></td><td>Default</td><td>Character set, Text only</td></tr><tr><td><strong>Template</strong></td><td></td><td>Content written</td></tr></tbody></table><h2 id="http-sender" tabindex="-1">HTTP Sender <a class="header-anchor" href="#http-sender" aria-label="Permalink to &quot;HTTP Sender&quot;">​</a></h2><p>Makes an HTTP request and treats the reply as the response.</p><p><img src="'+g+'" alt="The HTTP Sender settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>URL</strong></td><td></td><td>Address the request goes to</td></tr><tr><td><strong>Method</strong></td><td>POST</td><td>POST, GET, PUT, DELETE, or PATCH</td></tr><tr><td><strong>Content</strong></td><td></td><td>Request body. Enabled only for POST, PUT, and PATCH, and greyed out when <strong>Content Type</strong> is <code>application/x-www-form-urlencoded</code></td></tr><tr><td><strong>Content Type</strong></td><td>text/plain</td><td>Value of the request&#39;s Content-Type header. Enabled only for POST, PUT, and PATCH. With <code>application/x-www-form-urlencoded</code>, the query parameters are encoded into the request body</td></tr><tr><td><strong>Data Type</strong></td><td>Text</td><td>Text or Binary. Binary base64 decodes the content before sending. Enabled only for POST, PUT, and PATCH, and greyed out with <code>application/x-www-form-urlencoded</code></td></tr><tr><td><strong>Charset Encoding</strong></td><td>UTF-8</td><td>Character set for the body. Enabled only for POST, PUT, and PATCH, with <strong>Data Type</strong> Text</td></tr><tr><td><strong>Multipart</strong></td><td>No</td><td>Send the request as multipart. Enabled only for POST, and greyed out and set to No with <code>application/x-www-form-urlencoded</code></td></tr><tr><td><strong>Send Timeout (ms)</strong></td><td>30000</td><td>Connect and socket timeout</td></tr><tr><td><strong>Headers</strong></td><td></td><td>Request headers. <strong>Use Map</strong> takes them from a map variable instead of the table</td></tr><tr><td><strong>Query Parameters</strong></td><td></td><td>Query string parameters, same <strong>Use Map</strong> option</td></tr><tr><td><strong>Authentication</strong></td><td>No</td><td>Send credentials with the request</td></tr><tr><td><strong>Authentication Type</strong></td><td>Basic</td><td>Basic or Digest. The <strong>Preemptive</strong> checkbox beside them is off by default and sends the authorization header with the initial request, instead of only when the server asks. With Digest, the engine answers the server&#39;s 401 challenge with a second request that carries the computed Authorization header, so the Headers table needs no Authorization entry. With <strong>Preemptive</strong> on, the engine reads an Authorization: Digest header from the Headers table, takes its parameters (such as realm, nonce, algorithm and qop), and sends the computed header on the first request. With <strong>Preemptive</strong> on and no such header, Digest behaves as with <strong>Preemptive</strong> off</td></tr><tr><td><strong>Username</strong> / <strong>Password</strong></td><td></td><td>Credentials</td></tr><tr><td><strong>Use Proxy Server</strong></td><td>No</td><td>Route through a proxy</td></tr><tr><td><strong>Proxy Address</strong> / <strong>Proxy Port</strong></td><td></td><td>The proxy</td></tr><tr><td><strong>Override Local Binding</strong></td><td>No</td><td>Bind a specific local address for the outbound connection. No uses 0.0.0.0</td></tr><tr><td><strong>Local Address</strong></td><td>0.0.0.0</td><td>The local address the connection is bound to. Enabled only when <strong>Override Local Binding</strong> is Yes, and the value may use Velocity replacement</td></tr><tr><td><strong>Response Content</strong></td><td>Plain Body</td><td>Plain Body passes the reply body through as a raw string. XML Body returns the body as XML, and adds the status line and headers only when <strong>Include Metadata</strong> is Yes</td></tr><tr><td><strong>Parse Multipart</strong></td><td>Yes</td><td>Split a multipart reply into parts. XML Body only</td></tr><tr><td><strong>Include Metadata</strong></td><td>No</td><td>Include status line and headers. XML Body only</td></tr><tr><td><strong>Binary MIME Types</strong></td><td><code>application/.*(?&lt;!json|xml)$|image/.*|video/.*|audio/.*</code></td><td>Reply content types treated as binary and base64 encoded. The <strong>Regular Expression</strong> checkbox is on by default; unchecked, enter several types separated by commas</td></tr></tbody></table><h2 id="javascript-writer" tabindex="-1">JavaScript Writer <a class="header-anchor" href="#javascript-writer" aria-label="Permalink to &quot;JavaScript Writer&quot;">​</a></h2><p>Runs a script, which can send data anywhere itself or nowhere at all. What the script returns decides the response: nothing at all is a SENT with <em>JavaScript evaluation successful.</em>, a <code>Response</code> is used as-is, a <code>Status</code> sets only the status, and anything else becomes the response data. A script that throws gives ERROR.</p><p><img src="'+c+'" alt="The JavaScript Writer settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>JavaScript</strong></td><td>The script to run</td></tr></tbody></table><p>Unlike the JavaScript Reader, this connector has the full message scope: <code>channelMap</code>, <code>connectorMap</code>, <code>sourceMap</code>, <code>responseMap</code>, and <code>connectorMessage</code> are all available. See <a href="./script_scope_and_user_api.html">Script Scope and User API</a>.</p><h2 id="jms-sender" tabindex="-1">JMS Sender <a class="header-anchor" href="#jms-sender" aria-label="Permalink to &quot;JMS Sender&quot;">​</a></h2><p>Publishes to a JMS queue or topic. The connection fields are the same as the <a href="./connector_reference_sources.html#jms-listener">JMS Listener</a>, except that there is no <strong>Durable</strong> checkbox: <strong>Use JNDI</strong>, <strong>Provider URL</strong>, <strong>Initial Context Factory</strong>, <strong>Connection Factory Name</strong>, <strong>Connection Factory Class</strong>, <strong>Connection Properties</strong>, <strong>Username</strong>, <strong>Password</strong>, <strong>Client ID</strong>, <strong>Destination Type</strong>, and <strong>Destination Name</strong>. <strong>Use JNDI</strong> Yes greys out <strong>Destination Type</strong> and <strong>Connection Factory Class</strong>. No greys out <strong>Provider URL</strong>, <strong>Initial Context Factory</strong>, and <strong>Connection Factory Name</strong>. As for the <a href="./connector_reference_sources.html#jms-listener">JMS Listener</a>, select the library resource with the provider&#39;s client jars on this destination&#39;s own entry in <strong>Set Dependencies</strong> &gt; <strong>Library Resources</strong>; without it the send is ERROR with a <code>ClassNotFoundException</code> for the factory class.</p><p><img src="'+l+'" alt="The JMS Sender settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Template</strong></td><td><code>${message.encodedData}</code></td><td>Message body published</td></tr></tbody></table><h2 id="smtp-sender" tabindex="-1">SMTP Sender <a class="header-anchor" href="#smtp-sender" aria-label="Permalink to &quot;SMTP Sender&quot;">​</a></h2><p>Sends email.</p><p><img src="'+p+'" alt="The SMTP Sender settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>SMTP Host</strong></td><td></td><td>Mail server</td></tr><tr><td><strong>SMTP Port</strong></td><td>25</td><td>Mail server port</td></tr><tr><td><strong>Override Local Binding</strong></td><td>No</td><td>Bind a specific local address and port for the outbound connection</td></tr><tr><td><strong>Local Address</strong> / <strong>Local Port</strong></td><td>0.0.0.0 / 0</td><td>The local binding. Enabled only when <strong>Override Local Binding</strong> is Yes</td></tr><tr><td><strong>Send Timeout (ms)</strong></td><td>5000</td><td>Connect and socket timeout</td></tr><tr><td><strong>Encryption</strong></td><td>None</td><td>None, STARTTLS, or SSL</td></tr><tr><td><strong>Use Authentication</strong></td><td>No</td><td>Authenticate to the server. No greys out <strong>Username</strong> and <strong>Password</strong></td></tr><tr><td><strong>Username</strong> / <strong>Password</strong></td><td></td><td>SMTP credentials</td></tr><tr><td><strong>To</strong></td><td></td><td>Recipients, comma separated</td></tr><tr><td><strong>From</strong></td><td></td><td>Sender address</td></tr><tr><td><strong>Subject</strong></td><td></td><td>Subject line of the email</td></tr><tr><td><strong>Charset Encoding</strong></td><td>Default</td><td>Character set for the body</td></tr><tr><td><strong>HTML Body</strong></td><td>No</td><td>Send the body as HTML rather than plain text</td></tr><tr><td><strong>Body</strong></td><td></td><td>Body of the email</td></tr><tr><td><strong>Headers</strong></td><td></td><td>Additional headers. <strong>Use Map</strong> takes them from a map variable</td></tr><tr><td><strong>Attachments</strong></td><td></td><td>Files attached, each with a name, content, and MIME type. <strong>Use List</strong> takes them from a list variable</td></tr></tbody></table><p>The Administrator has fields for <strong>To</strong> and <strong>From</strong> only. <code>cc</code>, <code>bcc</code>, and <code>replyTo</code> exist in the connector&#39;s saved properties but have no field.</p><h2 id="tcp-sender" tabindex="-1">TCP Sender <a class="header-anchor" href="#tcp-sender" aria-label="Permalink to &quot;TCP Sender&quot;">​</a></h2><p>Opens a TCP connection and sends the message, MLLP framing included.</p><p><img src="'+u+'" alt="The TCP Sender settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>Mode</strong></td><td>Client</td><td>Client connects out, and is the only mode with <strong>Remote Address</strong>, <strong>Remote Port</strong>, <strong>Override Local Binding</strong>, and <strong>Keep Connection Open</strong>. Server binds and waits, and is the only mode with <strong>Max Connections</strong></td></tr><tr><td><strong>Remote Address</strong></td><td>127.0.0.1</td><td>Where to connect</td></tr><tr><td><strong>Remote Port</strong></td><td>6660</td><td>Port to connect to</td></tr><tr><td><strong>Override Local Binding</strong></td><td>No</td><td>Bind a specific local address and port. Client mode only</td></tr><tr><td><strong>Local Address</strong> / <strong>Local Port</strong></td><td>0.0.0.0 / 0</td><td>The local binding. Enabled in Server mode, or in Client mode when <strong>Override Local Binding</strong> is Yes</td></tr><tr><td><strong>Send Timeout (ms)</strong></td><td>5000</td><td>How long to keep the connection open when <strong>Keep Connection Open</strong> is Yes. 0 keeps it open indefinitely. Enabled only when <strong>Keep Connection Open</strong> is Yes</td></tr><tr><td><strong>Buffer Size (bytes)</strong></td><td>65536</td><td>Applied to both the socket receive buffer and the socket send buffer, and to the output stream buffer</td></tr><tr><td><strong>Max Connections</strong></td><td>10</td><td>Concurrent connections accepted. Server mode only</td></tr><tr><td><strong>Keep Connection Open</strong></td><td>No</td><td>Hold the connection open between messages. Client mode only, and Yes is what enables <strong>Send Timeout</strong> and <strong>Check Remote Host</strong></td></tr><tr><td><strong>Check Remote Host</strong></td><td>No</td><td>Test the connection is still alive before sending. Enabled only when <strong>Keep Connection Open</strong> is Yes</td></tr><tr><td><strong>Response Timeout (ms)</strong></td><td>5000</td><td>Wait for a reply. Also used as the connect timeout</td></tr><tr><td><strong>Ignore Response</strong></td><td>No</td><td>A checkbox beside <strong>Response Timeout</strong>. Sends without waiting for a reply, and ticking it disables <strong>Queue on Response Timeout</strong></td></tr><tr><td><strong>Queue on Response Timeout</strong></td><td>Yes</td><td>Queue the message when no reply arrives, rather than erroring. Has no effect unless the destination queue is on</td></tr><tr><td><strong>Data Type</strong></td><td>Text</td><td>Text or Binary. Binary base64 decodes before sending</td></tr><tr><td><strong>Encoding</strong></td><td>Default</td><td>Character set, Text only</td></tr><tr><td><strong>Transmission Mode</strong></td><td>MLLP</td><td>MLLP or Basic TCP. <strong>Sample Frame</strong> previews the framing bytes. See <a href="./connector_reference_sources.html#transmission-modes">transmission modes</a></td></tr><tr><td><strong>Template</strong></td><td><code>${message.encodedData}</code></td><td>Content sent</td></tr></tbody></table><p><strong>Validate Response</strong> is on by default for this destination.</p><h2 id="web-service-sender" tabindex="-1">Web Service Sender <a class="header-anchor" href="#web-service-sender" aria-label="Permalink to &quot;Web Service Sender&quot;">​</a></h2><p>Calls a SOAP operation.</p><p><img src="'+m+'" alt="The Web Service Sender settings on the channel editor&#39;s Destinations tab"></p><table tabindex="0"><thead><tr><th>Setting</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><strong>WSDL URL</strong></td><td></td><td>WSDL to read. <strong>Get Operations</strong> populates the fields below from it</td></tr><tr><td><strong>Service</strong></td><td></td><td>Service from the WSDL</td></tr><tr><td><strong>Port / Endpoint</strong></td><td></td><td>Port from the WSDL</td></tr><tr><td><strong>Location URI</strong></td><td></td><td>Endpoint address, when it differs from the one in the WSDL</td></tr><tr><td><strong>SOAP Action</strong></td><td></td><td>SOAPAction header</td></tr><tr><td><strong>Operation</strong></td><td>Press Get Operations</td><td>Operation from the WSDL. Used to generate the <strong>SOAP Envelope</strong> and fill in <strong>SOAP Action</strong>, and not read when the message is sent</td></tr><tr><td><strong>SOAP Envelope</strong></td><td></td><td>The envelope sent. Generated from the WSDL, then edited</td></tr><tr><td><strong>Invocation Type</strong></td><td>Two-Way</td><td>Two-Way waits for a response, One-Way does not</td></tr><tr><td><strong>Socket Timeout (ms)</strong></td><td>30000</td><td>Connection and socket timeout. 0 is infinite</td></tr><tr><td><strong>Authentication</strong></td><td>No</td><td>Send credentials with the request. They are also used to fetch the WSDL</td></tr><tr><td><strong>Username</strong> / <strong>Password</strong></td><td></td><td>Credentials</td></tr><tr><td><strong>Headers</strong></td><td></td><td>Request headers. <strong>Use Map</strong> takes them from a map variable</td></tr><tr><td><strong>Use MTOM</strong></td><td>No</td><td>Send attachments as MTOM</td></tr><tr><td><strong>Attachments</strong></td><td></td><td>Attachments, each with an <strong>ID</strong>, <strong>Content</strong> (Base64 encoded), and <strong>MIME Type</strong>. The table is enabled only when <strong>Use MTOM</strong> is Yes. <strong>Use List</strong> takes them from a list variable</td></tr></tbody></table>',74)]))}const C=e(b,[["render",f]]);export{P as __pageData,C as default};
